PVD("samoa_sector_sam-energy-sector-plan-2023-27",{"docs":["","SAM Energy Sector Plan 2023 27"],"s":{"1":[[1,"3","3","Inclusive energy planning and management framework (also read at p.13 §3)","develop a comprehensive and inclusive approach to energy planning and management",""]],"2":[[1,"5","2","Renewable energy investment and usage expansion (also read at p.13 §5; p.17 §7; p.19 §3; p.19 §6; p.19 §8; p.29 §3; p.36 §2; p.13 §6; p.19 §7; p.20 §2; p.22 §5; p.22 §9; p.11 §4; p.13 §7; p.17 §9; p.24 §3; p.24 §7; p.24 §8; p.25 §4; p.48 §13; p.13 §8; p.25 §7; p.29 §7; p.10 §7; p.20 §5; p.21 §8; p.36 §3; p.29 §4; p.22 §8; p.36 §7)","Expand Investments and Usage of Renewable Energy",""]],"3":[[1,"12","3","Electric vehicle adoption and enabling support (also read at p.26 §2; p.28 §4; p.28 §5; p.33 §8; p.36 §5; p.25 §8; p.26 §5; p.27 §3; p.27 §7; p.27 §8; p.27 §4; p.33 §11; p.26 §3; p.26 §4)","EPC has piloted a few electric vehicles in the country",""]],"4":[[1,"20","3","Community participation and partnerships for small-scale renewable energy initiatives (also read at p.20 §4; p.29 §4; p.20 §5; p.29 §5)","Increase community participation through small scale initiatives",""]],"5":[[1,"20","6","Solar street light promotion and procurement (also read at p.36 §3)","promote solar street lights to power its infrastructure and national parks",""]],"6":[[1,"21","6","Electricity loss reduction and grid modernization (also read at p.21 §7; p.22 §7; p.36 §4; p.47 §11)","reduce losses due to generation, transmission & distribution of electricity",""]],"7":[[1,"25","3","HSSE standards compliance for petroleum facilities (also read at p.33 §10; p.34 §3)","Ensuring compliance with the Health, Safety, Security, and Environment standards (HSSE)",""]],"8":[[1,"25","5","Waste-to-energy pathway development","Develop a proper pathway for waste to energy",""]],"9":[[1,"27","5","Shared mobility, public transport, and non-motorized transport promotion (also read at p.27 §6; p.28 §3)","Encourage shared mobility and public transportation",""]],"10":[[1,"29","8","Inclusive participation of vulnerable groups in energy policy and programmes (also read at p.35 §5; p.35 §6; p.36 §12; p.47 §6; p.47 §11)","The Plan recognizes the inclusion of vulnerable groups in the development and implementation of energy policies and programs",""]],"11":[[1,"32","3","Energy sector governance, coordination, and oversight framework (also read at p.32 §5; p.32 §6; p.33 §2; p.33 §6; p.33 §7; p.46 §18; p.46 §22; p.35 §8)","sector coordination framework",""]],"12":[[1,"35","3","Energy data management system review and digital project management platforms (also read at p.35 §3; p.46 §19)","Reviewing and updating the established data management system",""]],"13":[[1,"36","6","Energy-efficient appliance and HVAC investment programme","Investing in the import, distribution and installation of EE appliances, lighting, Heating, Ventilation and Air Conditioning (HVAC) systems",""]],"14":[[1,"36","9","Energy sector stakeholder engagement and communication strategy (also read at p.36 §13)","the Sector will focus on accurate information sharing, building productive partnerships with stakeholders and data providers",""]],"15":[[1,"36","11","Energy awareness and public education campaigns","Awareness campaigns to build support and educate the public on the benefits of EE and RE",""]],"16":[[1,"37","2","Annual, mid-term, and results-based monitoring of the energy sector plan (also read at p.38 §3; p.46 §24)","Annual and Mid-Term Review of the SESP",""]],"17":[[1,"48","11","Oil spill, chemical spill, and hazardous waste emergency response training (also read at p.48 §11; p.48 §11; p.48 §11)","Emergency Response for Chemical & Hazardous Waste Accident",""]],"18":[[1,"49","7","Energy sector stakeholder performance assessment and engagement","we should be able to assess stakeholder performances and functions",""]],"19":[[1,"49","9","Energy sector staff performance and activity monitoring systems","Develop work plans, progress reports or reporting and monitoring systems to monitor staff performance and the progress of divisional activities as well as Sector.",""]],"20":[[1,"49","12","Petroleum pricing training","Provide overseas training for petroleum personals for the development of pricing template and factors affecting the price;",""]],"21":[[1,"49","13","Fuel dispensing calibration and safety procedures training","Increased opportunity for overseas training on calibration/ servicing of dispensers, delivery trucks and new safety procedures provided.",""]],"22":[[1,"49","14","Local HSSE standards compliance training","Understanding the Health, Safety, Security and Environment standards requirements to apply locally.",""]],"23":[[1,"49","16","Energy project monitoring and evaluation capacity development","Develop skills and knowledge in Monitoring and Evaluation of Energy Related Project",""]],"24":[[1,"49","18","Regulated appliance test report identification training","Training for skills in identifying of Test Reports for all regulated appliances in the EE Act 2017",""]],"25":[[1,"49","19","Pacific appliance and labeling database upgrade","Upgrading the Pacific Appliance and Labeling Database and data entry",""]],"26":[[1,"50","4","Energy sector governance framework","Establish a strong governance framework for the energy sector with clear policies, plans, legislation, institutional and organizational arrangements that are interlinked;",""]],"27":[[1,"50","5","Harmonized investment environment for energy sector partners","Establish a harmonized and engaging environment for regional and international entities, development partners and investors;",""]],"28":[[1,"50","6","Energy sector management and coordination oversight","Oversee the energy sector management and coordination;",""]],"29":[[1,"50","7","Energy sector stakeholder coordination and reporting","Coordinate all key Government stakeholders in the energy sector and to report on any matters relating to energy;",""]],"30":[[1,"50","8","Energy mainstreaming in government decision-making and budget processes","Promote the mainstreaming of energy in all sectors and decision-making processes within Government and budgetary processes;",""]],"31":[[1,"50","11","Energy policy and project implementation oversight and evaluation","Oversee and evaluate implementation of energy related policies and projects;",""]],"32":[[1,"50","12","Energy review approval and cabinet submission mechanism","to approve energy related reviews and activities before implementation or onward submission to Cabinet",""]],"33":[[1,"50","13","Energy development regulation and management","Regulate and manage all energy related developments;",""]],"34":[[1,"50","14","Energy policy development and renewable energy promotion","Develop energy related policies, including policies that promote the development of renewable energy;",""]],"35":[[1,"50","15","Energy sector consultation and partnership coordination","Facilitate consultation with regional and international agencies and development partners relating to energy activities and programs;",""]],"36":[[1,"50","16","Oversight of regional and international energy projects","any regional or international energy related projects on bilateral or multilateral agreements",""]],"37":[[1,"50","17","Energy awareness day coordination","Coordinate with all the stakeholders regarding Energy Awareness Day.",""]],"38":[[1,"51","4","Energy sector plan coordination and monitoring","leading, coordinating and monitoring the implementation of the Samoa Energy Sector Plan together with the support of the Implementing Agencies",""]]}});
PVD("samoa_sector_sam-health-sector-plan-2020-30",{"docs":["","SAM Health Sector Plan 2020 30"],"s":{"1":[[1,"2","3","Ministry of Health structural and administrative reform (also read at p.11 §2; p.3 §3; p.9 §4; p.33 §2; p.41 §5; p.6 §2; p.19 §2; p.30 §3; p.31 §2; p.31 §4; p.37 §4; p.41 §6; p.7 §2; p.18 §2; p.20 §2; p.32 §6; p.32 §7; p.32 §8; p.39 §3; p.40 §2; p.12 §2; p.14 §2; p.34 §2; p.41 §3; p.17 §2; p.15 §2; p.16 §2; p.21 §2; p.35 §2; p.23 §5)","the Government of Samoa has instituted structural and administrative changes for the Ministry of Health (MOH).",""]],"2":[[1,"28","7","Water safety plan development for water schemes","Water Safety plans for independent water schemes developed and implemented",""]],"3":[[1,"41","7","E-health and health information system strengthening and testing (also read at p.42 §5)","Finalising the e-health system and health information system, and testing it to ensure it is working as intended",""]],"4":[[1,"41","8","National Health Accounts updating","Updating the NHA, including with better data",""]],"5":[[1,"42","3","Tobacco excise duty increase","Raising the excise duty on tobacco to 70% of the retail price",""]],"6":[[1,"42","7","Program budgeting and reporting for health sector resource management","A shift to program budgeting and reporting will give a more informed evidence base on how to respond to any budget cuts",""]]}});
PVD("samoa_sector_sam-national-adaptation-plan-2026",{"docs":["","SAM National Adaptation Plan 2026"],"s":{"1":[[1,"4","1","National adaptation planning and climate risk mainstreaming framework (also read at p.4 §2; p.4 §3; p.4 §10; p.4 §11; p.4 §13; p.4 §14; p.4 §15; p.4 §20; p.4 §22; p.4 §23; p.14 §5; p.20 §4; p.21 §2; p.12 §11; p.20 §13; p.21 §1; p.22 §1; p.24 §8; p.54 §3; p.11 §5; p.32 §10; p.20 §9; p.20 §10; p.30 §1; p.18 §8; p.19 §2; p.16 §5; p.21 §8; p.22 §9; p.26 §2; p.53 §6; p.12 §9; p.14 §3; p.19 §4; p.19 §7; p.20 §7; p.22 §6; p.30 §3; p.31 §2; p.44 §17; p.23 §12; p.26 §1; p.20 §3; p.23 §10; p.27 §5; p.22 §3; p.22 §5; p.22 §8; p.29 §2; p.29 §3; p.29 §5; p.31 §6; p.32 §7; p.44 §14; p.77 §5)","supports the integration of climate risk into policy, planning, and budgeting processes",""]],"2":[[1,"11","13","Health sector climate adaptation","Health sector is a critical component of climate change adaptation",""]],"3":[[1,"12","5","Early warning systems and climate-resilient infrastructure","Building early warning systems, climate-resilient or disaster proof infrastructure",""]],"4":[[1,"15","7","Mangrove restoration and planting programme (also read at p.15 §8; p.53 §8)","Mangrove restoration  and  planting  programs in coastal  areas.",""]],"5":[[1,"15","10","Awareness raising and seedling support for ecosystem restoration","Awareness raising activities and targeted support, including provision of seedlings.",""]],"6":[[1,"15","11","Agroforestry expansion support","promote the expansion of agroforestry",""]],"7":[[1,"15","13","Reforestation and forest restoration programme (also read at p.16 §3)","Develop a program for reforestation and forest restoration",""]],"8":[[1,"18","11","Training for community adaptation stakeholders","Invests in training farmers, PWDsϭϴ, community leaders, and village councils",""]],"9":[[1,"23","5","Inclusive governance policy and representation mechanisms (also read at p.28 §5; p.28 §9; p.28 §10)","ensuring that all Samoans regardless of gender, ability, age, and background are included in decision-making processes at every level of governance",""]],"10":[[1,"30","2","Community resilience and local governance strengthening (also read at p.32 §3)","strengthening local governance and empowering vulnerable groups to respond to climate-related challenges",""]],"11":[[1,"52","30","Tourism-dependent community climate resilience project","Enhancing the Resilience of Tourism-reliant Communities to Climate Change Risks.",""]],"12":[[1,"33","11","Climate risk and vulnerability assessment system (also read at p.33 §12; p.34 §1; p.34 §2)","Characterize present-day climate risk by mapping exposure, sensitivity and adaptive capacity across sectors and social groups.",""]],"13":[[1,"44","9","Power plant refurbishment and grid battery storage upgrade","grid-scale batteries at Fiaga and Faleolo improve stability with >40% of RE share",""]],"14":[[1,"54","6","Climate risk and vulnerability assessment capacity and coordination (also read at p.55 §2; p.55 §3; p.55 §4)","Invest in capacity building initiatives to enhance the knowledge and skills of practitioners involved in the CRVA.",""]],"15":[[1,"55","1","Climate projection uncertainty assessment and communication","Engage individual climate scientists and experts to better understand the uncertainties and limitations of climate projections.",""]],"16":[[1,"55","5","Inclusive community engagement in climate risk and vulnerability assessment","Foster community engagement and participation, including the participation of vulnerable groups throughout the CRVA process.",""]],"17":[[1,"56","5","Climate risk avoidance in asset and settlement siting (also read at p.77 §1; p.58 §8)","steer new assets and settlements away from hazard zones",""]],"18":[[1,"57","2","District coastal infrastructure planning with sea-level-rise contours and setbacks","Update district CIM Plans with 30cm SLR contour and recommend coastal setbacks for all critical infrastructure",""]],"19":[[1,"57","3","Sea-level-rise buffer legal reform in planning law","consideration of making SLR buffer legally binding",""]],"20":[[1,"57","7","Climate-resilient crop, irrigation, and fish aggregation support for farms and communities (also read at p.59 §4; p.59 §6; p.57 §8; p.80 §4; p.81 §1; p.58 §1; p.60 §1; p.80 §1; p.80 §2; p.80 §3; p.80 §5; p.80 §7; p.81 §2)","Distribute salt-tolerant taro and irrigation drip kits to 2,500 farms",""]],"21":[[1,"58","4","Parametric sovereign disaster insurance coverage (also read at p.58 §5; p.58 §10; p.58 §12; p.60 §1)","Subscribe to PCRAFI 2.0 parametric cyclone cover",""]],"22":[[1,"58","9","Multi-hazard warning dashboard","Design / launch of multi-hazard warning dashboard",""]],"23":[[1,"59","1","Solar backup power and disaster planning for health facilities (also read at p.59 §7; p.82 §2)","Equip 100% of rural clinics with solar PV back-up, update of hospital disaster plans",""]],"24":[[1,"59","5","Small-scale desalination and aquifer storage and recovery exploration","exploration of small-scale desalination and aquifer storage and recovery (ASR) as adaptation measures",""]],"25":[[1,"69","1","Climate adaptation support for tourism sites and operators (also read at p.73 §1; p.73 §2; p.60 §16; p.69 §2)","Support climate adaptation and mitigation actions for tourism sites and operators",""]],"26":[[1,"69","3","Climate-resilient water quality monitoring and surveillance (also read at p.74 §2; p.74 §3; p.78 §4; p.69 §4)","Strengthen water quality monitoring to ensure climate-resilient water safety.",""]],"27":[[1,"68","6","Climate adaptation training and extension support for farmers and fishers (also read at p.69 §6; p.69 §7; p.68 §7; p.78 §2; p.81 §1)","Train and empower rural farmers and fishers to adapt to climate risks.",""]],"28":[[1,"68","8","Renewable energy and power systems capacity-building (also read at p.70 §1; p.70 §2; p.68 §9; p.78 §6; p.77 §12)","Build national capacity for managing renewable energy and power systems.",""]],"29":[[1,"68","10","Climate, water, land, and village development awareness campaigns (also read at p.71 §1; p.71 §2; p.78 §8; p.79 §21; p.68 §11; p.78 §2)","Deliver awareness campaigns on climate change, water, land, and village development.",""]],"30":[[1,"68","12","Climate-sensitive disease surveillance and response system (also read at p.72 §1; p.77 §11; p.68 §13; p.72 §2)","Enhance surveillance and response for climate-sensitive communicable and tropical diseases.",""]],"31":[[1,"76","2","National adaptation investment and implementation planning (also read at p.77 §9)","an investment and implementation plan is to be developed.",""]],"32":[[1,"76","4","Cross-cutting enablers for adaptation implementation","implementation of the twelve priority actions (two for each priority sector) should be embedded within the four cross-cutting, system-level enablers identified",""]],"33":[[1,"76","10","Integration of adaptation priority actions into planning and investment frameworks","Embed each priority action in sector plan reviews, CIM Plans, and the Public Investment Program.",""]],"34":[[1,"76","15","Cross-sector adaptation skills gap training and upskilling","Close skills gaps through training mechanisms / facilities that provide standard designs, safeguard checklists, GEDSI guidelines, and joint training / upskilling.",""]],"35":[[1,"76","20","Multi-year climate finance windows","Bundle actions into multi-year finance windows",""]],"36":[[1,"77","4","National climate change trust fund","Could a national Climate Change Trust Fund pool donor and domestic resources?",""]],"37":[[1,"81","4","Climate-resilient WASH infrastructure and inclusive service delivery","promoting climate resilient water infrastructure",""]],"38":[[1,"81","5","Climate-resilient energy infrastructure development (also read at p.82 §1)","development of climate-resilient energy infrastructure, particularly for rural and remote areas",""]],"39":[[1,"82","3","Climate-resilient tourism infrastructure","building climate resilient infrastructure",""]],"40":[[1,"82","5","National adaptation plan implementation","supports the implementation of adaptation actions",""]],"41":[[1,"82","6","Community Integrated Management Plan review and update (also read at p.91 §17; p.83 §2)","A systematic review and update of the CIM Plans is strongly recommended",""]],"42":[[1,"84","1","Adaptation financing mobilization (also read at p.85 §2)","continue to develop and leverage existing financing options",""]],"43":[[1,"84","3","Climate readiness and preparatory support programme (also read at p.86 §1; p.86 §2; p.91 §17; p.92 §2)","strengthen technical capacity of relevant stakeholders",""]],"44":[[1,"86","4","Climate finance donor coordination mechanism","effective in-country donor coordination mechanisms",""]],"45":[[1,"86","5","National climate change coordination committee establishment (also read at p.86 §6; p.87 §1)","working on establishing a NCCC",""]],"46":[[1,"87","5","National adaptation monitoring, evaluation, and learning system (also read at p.88 §2; p.89 §2; p.91 §13; p.92 §1)","a comprehensive Monitoring, Evaluation, and Learning (MEL) system is essential",""]],"47":[[1,"87","4","Climate investment capacity and private sector project development support","develop investment- grade projects that can attract financiers",""]],"48":[[1,"90","1","Climate-responsive agricultural research","Research into farming techniques that accommodate climate change",""]],"49":[[1,"92","3","National climate adaptation plan implementation","a clear implementation trajectory from policy to action",""]]}});
PVD("samoa_sector_sam-national-employment-policy-2021-26",{"docs":["","SAM National Employment Policy 2021 26"],"s":{"1":[[1,"7","1","National employment policy implementation and review (also read at p.12 §1; p.13 §2; p.25 §8; p.9 §12; p.22 §1; p.22 §2; p.25 §3; p.21 §3; p.9 §10; p.24 §5; p.24 §9; p.26 §3; p.24 §7; p.24 §8; p.24 §11; p.31 §1; p.28 §11; p.24 §18; p.24 §19; p.24 §20; p.25 §1; p.25 §2; p.27 §7; p.28 §9; p.24 §6; p.24 §10; p.26 §6; p.29 §19; p.30 §1; p.26 §11; p.29 §9; p.30 §8; p.30 §9; p.30 §11; p.29 §13; p.29 §14)","the formulation of this second SNEP anticipated for the period starting from FY 2021/22 to FY 2025/26; builds on the review of the first SNEP",""]],"2":[[1,"9","11","Rapid support for workers unemployed due to COVID-19 (also read at p.24 §13; p.32 §2; p.24 §15; p.24 §17; p.24 §18; p.24 §11; p.24 §19; p.30 §12; p.32 §6; p.32 §10; p.33 §2; p.33 §3)","Provide rapid support to those who have become unemployed due to COVID-19.",""]],"3":[[1,"24","16","Child labour reintegration into the education system (also read at p.33 §15; p.46 §17)","Reintegrate child labour into the education system in-line with the compulsory education Policy of GOS.",""]],"4":[[1,"24","18","Female employment promotion measures","Research and take effective actions to promote female employment.",""]],"5":[[1,"24","19","ICT skills upskilling for the labour force","2.4.1. Upskill the labour force with relevant emerging skills in Information, Communication & Technology.",""]],"6":[[1,"24","20","Formalisation incentives and support for informal enterprises","Provide incentives via direct assistance and easing/simplifying reporting requirements for informal enterprises/businesses.",""]],"7":[[1,"24","21","Institutional strengthening for labour market policy promotion","3.1.1 Strengthen MCIL and NGO to effectively promote labour market policies.",""]],"8":[[1,"25","1","Incorporation of decent employment standards into employment regulations","Fully incorporate decent employment standards into Samoa’s Employment Regulatory framework for a covid19 build back better employment labour market",""]],"9":[[1,"23","1","Employment policy and regulatory framework review","Policy and Regulatory frameworks need to be consistently monitored and updated to ensure a proactive approach is taken in discussing and tabling employment issues.",""]],"10":[[1,"18","1","Youth self-employment and business start-up support (also read at p.18 §2; p.18 §5; p.33 §2)","Providing support for youth (Financial Management, Business Planning) to set up business ventures through the Samoa Business Hub.",""]],"11":[[1,"33","6","Pre-departure, reintegration, and behaviour training for labour mobility workers (also read at p.33 §8)","MCIL to strengthen pre-departure and reintegration training for labour mobility workers.",""]],"12":[[1,"21","5","Feasibility study for a national employment authority (also read at p.41 §3; p.49 §19)","This is to conduct a feasibility study to explore the merits and costs in establishing such as dedicated national authority.",""]],"13":[[1,"26","9","Domestic tourism package development and local hospitality promotion (also read at p.26 §10)","Samoa Tourism Authority (STA) and hospitality industries to develop in-partnership packages that would increase domestic tourism.",""]],"14":[[1,"29","11","COVID-19 compliance coordination for travellers in tourism","work closely with the MOH and front-line agencies; reach reasonable COVID-19 compliance requirements for travellers",""]],"15":[[1,"27","2","Seafarer re-employment negotiation initiative","Samoa Shipping Services (SSS) to negotiate with cruise liners and cargo ships for re-employment of Seafarers.",""]],"16":[[1,"27","5","Local product marketing and consumer information (also read at p.31 §9; p.28 §7)","having accessible, and understandable product information for locals would ensure their long-term commitment to a product.",""]],"17":[[1,"27","6","Marketing and tax protection for local produce and crops (also read at p.27 §9; p.28 §3)","more marketing of local produce and direct tax protection for8 selected products based on health benefits",""]],"18":[[1,"28","12","Government incentive and stimulus measures for employment retention (also read at p.28 §13; p.28 §16; p.29 §2; p.29 §3)","further explore and roll-out additional stimulus packages to sustain the current levels of employment, to prevent it from declining further",""]],"19":[[1,"24","12","Private sector capacity strengthening for goods and services supply","Strengthen the Private Sector capacity to sustain the supply of their goods and services to the local and international demand.",""]],"20":[[1,"24","14","Tailored PSET training provision (also read at p.32 §9)","Provide the necessary tailored trainings at the PSET level.",""]],"21":[[1,"30","13","Compulsory business tax system incorporation","compulsory incorporation of all licensed businesses in the tax system",""]],"22":[[1,"30","15","Compulsory employer incorporation into the national provident fund (also read at p.46 §8)","start compulsory incorporation of all employers into the fund",""]],"23":[[1,"31","2","Scientific research organisation establishment","this was a justification for the establishment of the Scientific Research Organisation of Samoa (SROS).",""]],"24":[[1,"31","7","Private sector research and development support for import substitution","support the Private Sector in research and development of additional goods that could be reasonably substituted and sustained in Samoa",""]],"25":[[1,"31","11","Excise and tariff measures for unhealthy and substitutable imported foods","imposing excise tax on nutritional-deficient food products; and increasing the tariff for imported products that could be sustainably substituted in Samoa",""]],"26":[[1,"33","10","Child labour and street vendor reduction measures (also read at p.33 §16; p.47 §1)","Take decisive actions in dealing with issues related to child labour and street vendors.",""]],"27":[[1,"34","9","Research on barriers to women's labour market participation (also read at p.47 §3)","conduct a research on the underlying barriers for women in the labour market.",""]],"28":[[1,"34","11","PSET training, upskilling, and reskilling opportunities for women (also read at p.47 §4)","provide PSET training, upskilling, and reskilling opportunities targeting women",""]],"29":[[1,"34","13","Tailored employment services for women (also read at p.47 §5)","MCIL to offer tailored employment services for women.",""]],"30":[[1,"34","14","Public awareness of workplace harassment provisions in the labour law (also read at p.47 §6)","conduct public awareness of the updated LERA, especially on provisions that cover harassment in the workplace.",""]],"31":[[1,"34","20","Employment pathways integration in education programmes (also read at p.47 §9)","Education Institutions to incorporate employment prospects and pathways for the programs they offer.",""]],"32":[[1,"35","3","Workplace accessibility infrastructure for persons with disabilities (also read at p.47 §10)","incorporate infrastructure that promote access for PwD in their businesses and workplaces.",""]],"33":[[1,"35","6","Incorporation of disability issues into labour policy and regulation (also read at p.47 §11)","ensure the PwD issues are incorporated into the labour Policy and Regulatory framework.",""]],"34":[[1,"35","12","Curriculum modernisation and review for employment responsiveness","modernising and continuous reviewing of curriculums and the National Human Resource Development Needs, to ensure they are responsive to development and employment needs.",""]],"35":[[1,"35","15","Curriculum review to integrate information technology skills (also read at p.47 §12)","review their curriculum and include teachings and theories on the different fields of information technology.",""]],"36":[[1,"35","17","Access to online teaching and training materials (also read at p.35 §18; p.47 §13)","Promote access to online training material for PSET and on-the-job training.",""]],"37":[[1,"36","2","Review and update of national human resource development needs (also read at p.47 §14)","PSC to review and update the Samoa National HRD Needs to refocus on emerging skills needed.",""]],"38":[[1,"36","4","Labour market survey revision for green jobs and skills shortages (also read at p.47 §15)","review the Labour Market Survey questionnaire to include better coverage of Green Jobs and Private Sector training needs and skills shortage.",""]],"39":[[1,"36","6","Incorporation of private sector human resource needs into HRD planning","ensure incorporation of Private Sector HRD needs into their review and update.",""]],"40":[[1,"36","8","Informal employment formalisation measures (also read at p.36 §9; p.36 §11; p.36 §19; p.37 §3)","Progress work to incorporate informal employees into the formal sector.",""]],"41":[[1,"36","12","Social protection and financial credibility measures for informal sector workers","building the Social Protection and financial credibility of all employees in the informal sector.",""]],"42":[[1,"36","14","Incentives and simplified reporting for informal enterprise formalisation (also read at p.36 §15; p.47 §17)","Provide incentives via direct assistance and easing/simplifying reporting requirements for informal enterprises/businesses.",""]],"43":[[1,"36","17","Tax and statutory compliance training for informal enterprises (also read at p.47 §18)","provide trainings for Informal Enterprises/Businesses on Income Tax and VAGST Reporting obligation.",""]],"44":[[1,"36","20","Apprenticeship scheme for informal sector workers transitioning to formality (also read at p.47 §19)","offer apprenticeship scheme for employees in the informal sector that have committed to transition to the formal sector.",""]],"45":[[1,"36","22","Compulsory statutory employee contribution enforcement","Enforce compulsory statutory contributions for all employees.",""]],"46":[[1,"36","23","Public awareness on statutory deductions (also read at p.47 §20)","roll-out public awareness campaign on statutory deductions",""]],"47":[[1,"37","1","Accident compensation process modernisation (also read at p.48 §2)","modernise and streamline their processes for easy access of employees.",""]],"48":[[1,"37","4","Expansion of labour law coverage to informal sector employment grievances (also read at p.48 §3)","ensure the LERA scope expands to cover under-reported employment grievances in the informal sector.",""]],"49":[[1,"38","3","Capacity building for labour market policy and standards institutions","improving MCIL and relevant NGO’s capacity including SNTF to promote relevant labour market policies, improve compliance and to develop national labour standards.",""]],"50":[[1,"38","4","Occupational safety and health standards strengthening","greater emphasis on OSH through a collaboration of relevant MCIL Divisions",""]],"51":[[1,"38","11","Labour standards compliance monitoring and inspection (also read at p.38 §12; p.48 §6; p.49 §4)","conduct monitoring visits and spot-checks to ensure compliance of employers and employees with labour standards.",""]],"52":[[1,"38","14","Access strengthening for employment mediation services (also read at p.48 §7; p.49 §6)","strengthen the accessibility of employees and employers to their mediation services.",""]],"53":[[1,"38","16","Capacity strengthening for employment grievance mediation services (also read at p.48 §8; p.49 §8)","strengthen their capacities to provide mediation services for employment grievances.",""]],"54":[[1,"38","18","Enterprise labour standards accreditation programme (also read at p.48 §9)","Develop a program for enterprises/businesses that would like to be accredited according to compliance with national labour standards",""]],"55":[[1,"38","20","National labour standard compliance index (also read at p.48 §10)","Develop a National Labour Standard Compliance Index",""]],"56":[[1,"39","2","Employment regulatory framework review for decent work standards (also read at p.39 §3; p.48 §11; p.48 §26)","review the LERA to align with decent employment standards.",""]],"57":[[1,"39","6","National minimum wage review (also read at p.48 §14; p.48 §28)","conduct timely reviews of the national minimum wage.",""]],"58":[[1,"39","7","Working-age population data review for policymaking (also read at p.48 §16; p.48 §29)","review the working age population to ensure uniformity of data and information for policymaking",""]],"59":[[1,"39","9","Ratification and compliance with labour conventions (also read at p.48 §18; p.49 §1)","continue the ratification and compliance with labour conventions",""]],"60":[[1,"39","10","Expansion of labour law coverage to unpaid domestic and household care work (also read at p.48 §20; p.49 §2)","ensure the LERA scope expands to cover unpaid domestic and household care work.",""]],"61":[[1,"39","12","Occupational safety and health monitoring including workplace mental health","Occupational Safety and Health (OSH) monitoring including mental health at the workplace",""]],"62":[[1,"39","13","Occupational safety and health awareness programmes (also read at p.48 §21)","Develop and implement awareness programs on Occupational Safety and Health (OSH) including mental health at the workplace",""]],"63":[[1,"39","16","Capacity building for NGOs providing employment services (also read at p.39 §17; p.39 §20; p.48 §23; p.39 §21; p.48 §5)","Provide support and capacity building initiatives to NGO’s providing employment related services.",""]],"64":[[1,"39","22","Employment services workshops with NGOs (also read at p.48 §24)","Conduct workshops between MCIL and selected NGO on relevant topics relating to employment services.",""]],"65":[[1,"40","7","Alignment of employment policy implementation with the national planning framework (also read at p.49 §10)","link in the implementation of the SNEP-2 to the overarching National Planning Framework.",""]],"66":[[1,"40","9","Employment policy linkages with education and economic sectors (also read at p.49 §11)","strengthen linkages of the SNEP-2 with the Education Sector and Economic Sectors to better link and facilitate labour demand and supply.",""]],"67":[[1,"40","11","Employment policy linkages with other economic and business policies (also read at p.49 §13)","strengthen linkages of the SNEP-2 with their other Policies",""]],"68":[[1,"40","13","Exploration of employment opportunities under PACER Plus","Explore employment-related opportunities available via the Pacific Agreement on Closer Economic Relations (PACER) Plus.",""]],"69":[[1,"40","14","Public awareness campaigns on PACER Plus trade in services and labour mobility (also read at p.49 §14)","roll-out public awareness campaigns on PACER Plus especially on Trade in Services and Labour Mobility.",""]],"70":[[1,"40","17","Institutional strengthening of implementing agencies for employment policy delivery (also read at p.49 §16)","Strengthen the institutional arrangements of Implementing Agencies to better implement the SNEP-2.",""]],"71":[[1,"41","1","Inter-ministerial coordination for employment policy implementation (also read at p.49 §17)","strengthen inter-ministerial networks, linkages, and cooperation to ensure inclusiveness and ownership of SNEP-2 implementation.",""]],"72":[[1,"41","4","Capacity strengthening for the Samoa National Tripartite Forum (also read at p.49 §20)","Strengthen the capacity of the SNTF to discuss and decide on employment matters.",""]],"73":[[1,"41","5","Information support to the Samoa National Tripartite Forum","provide thorough information to the SNTF to ensure they make informed and effective decisions.",""]],"74":[[1,"41","6","International labour developments information support for the Samoa National Tripartite Forum (also read at p.49 §21)","provide information on international labour developments that could influence the work of the SNTF.",""]],"75":[[1,"41","8","Monitoring and reporting of employment policy implementation (also read at p.41 §15; p.42 §6; p.49 §23)","Monitor and report the SNEP-2 for efficient and effective decision-making and future planning.",""]],"76":[[1,"41","11","Employment policy implementation coordination mechanism","improve and coordinate the SNEP-2 Implementation",""]],"77":[[1,"41","17","Mid-term and final evaluation of employment policy (also read at p.49 §25)","conduct the mid-term and final evaluation of the SNEP-2",""]],"78":[[1,"41","19","Employment policy realignment based on monitoring and evaluation findings (also read at p.49 §27)","take relevant SNEP-2 realignment based on findings from the M&E reports.",""]],"79":[[1,"43","2","Pilot employment policy project","It proposes a pilot project to be developed by IA’s and MCIL and DP’s",""]],"80":[[1,"45","2","Domestic tourism partnership packages","develop in-partnership packages that would increase domestic tourism.",""]],"81":[[1,"45","3","Local promotion of hospitality industries to stimulate domestic tourism demand","promote hospitality industries locally to attract local tourist demand.",""]],"82":[[1,"45","4","Targeted assistance for the tourism industry to sustain employment during COVID-19","increase targeted assistance for the Tourism industry to sustain their current COVID-19 levels of employment.",""]],"83":[[1,"45","5","Negotiation of labour mobility access pathways with reduced COVID-19 restrictions","continue negotiation with New Zealand (NZ) and Australia for convenient mobilising of workers with less stringent COVID-19 requirements.",""]],"84":[[1,"45","6","Seafarer re-employment negotiations with shipping lines","negotiate with cruise liners and cargo ships for re-employment of Seafarers.",""]],"85":[[1,"45","7","Promotion of local produce to increase domestic demand","promote local produces to increase the local demand.",""]],"86":[[1,"45","9","Expansion of financial literacy outreach and remittance reinvestment content","widen the reach of their financial literacy program, by scope (e.g. community outreach) and content (e.g. including remittances re-investment)",""]],"87":[[1,"45","10","Mainstreaming of employment policy into MSME, trade, and agriculture policy implementation","link the SNEP-2 into the work of other existing Policies",""]],"88":[[1,"45","11","Additional employment stimulus packages to sustain jobs during COVID-19","further explore and roll-out additional stimulus packages to sustain the current levels of employment",""]],"89":[[1,"45","12","Integration of employment generation into MSME policy roll-out","link in the SNEP-2 to the roll-out of the Samoa MSME Development Policy and Strategy to ensure employment generation remains a key component.",""]],"90":[[1,"45","13","Finalisation and roll-out of the national industrial development policy linked to employment policy","finalise and roll-out the National Industrial Development Policy (NIDP) and ensure linkages with the SNEP-2.",""]],"91":[[1,"45","14","Domestic and international promotion of the hospitality industry","continue local promotion while also restarting promotion to traditional markets.",""]],"92":[[1,"45","15","Tourism COVID-19 compliance coordination for travellers","work closely with the MOH and front-line agencies to reach reasonable COVID-19 compliance requirements for travellers",""]],"93":[[1,"46","1","Private sector supply chain substitution analysis and policy action","determine products that they can reasonably substitute and advise the GOS on the outcomes of their analysis for immediate policy action.",""]],"94":[[1,"46","2","Linkage of employment policy to national industrial development policy implementation","link in the SNEP-2 to the work of the NIDP.",""]],"95":[[1,"46","3","Restoration of labour mobility programme operations","continue discussions and negotiations with New Zealand and Australian Governments and Employers; resume full operations of the labour mobility programs",""]],"96":[[1,"46","4","Expansion of labour mobility programmes to additional industries","advance further negotiations with NZ and Australia; expansion of labour mobility programs to other industries",""]],"97":[[1,"46","5","International tourism promotion campaigns for emerging markets","reset international promotional campaigns with focus on emerging markets",""]],"98":[[1,"46","6","Competitive tourist package development for emerging markets","develop competitive package deals for tourists from emerging markets.",""]],"99":[[1,"46","7","Compulsory incorporation of licensed businesses into the tax system","consider compulsory incorporation of all licensed businesses in the tax system.",""]],"100":[[1,"46","9","Research and development support for local product substitution","support the Private Sector in research and development of additional goods that could be reasonably substituted and sustained in Samoa.",""]],"101":[[1,"46","10","Public nutrition awareness campaigns","conduct effective public awareness campaigns on nutrition.",""]],"102":[[1,"46","11","Excise taxes and tariff measures for unhealthy foods and local substitution","imposing excise tax on nutritional-deficient food products; increasing the tariff for imported products that could be sustainably substituted in Samoa",""]],"103":[[1,"46","12","Rapid support and tailored training for workers unemployed due to COVID-19","Provide rapid support to those who have become unemployed due to COVID-19.",""]],"104":[[1,"46","13","Upskilling and reskilling for laid-off workers","commit to upskilling and reskilling their laid off staff.",""]],"105":[[1,"46","14","Reskilling programme for labour mobility workers","Reskill the labour mobility workers.",""]],"106":[[1,"46","16","Pre-departure and reintegration training for labour mobility workers","strengthen pre-departure and reintegration training for labour mobility workers.",""]],"107":[[1,"47","8","Labour demand data integration into education policymaking","incorporate labour demand data and information in their policymaking.",""]]}});
