PVD("samoa_sector_sam-ocean-strategy-2020-30",{"docs":["","SAM Ocean Strategy 2020 30"],"s":{"1":[[1,"5","5","Integrated ocean management strategy implementation (also read at p.15 §3; p.31 §7; p.7 §14; p.31 §6; p.31 §12; p.31 §13; p.44 §3)","implement this Strategy for integrated management of its ocean",""]],"2":[[1,"7","11","National Ocean Steering Committee establishment (also read at p.29 §4; p.30 §2; p.30 §3; p.30 §4; p.30 §15; p.30 §16; p.44 §2)","Create a National Ocean Steering Committee",""]],"3":[[1,"7","16","Ocean scientific research, data collection, and monitoring improvement (also read at p.14 §5; p.27 §5; p.32 §2)","Improve scientific research, data collection and monitoring within Samoa’s ocean",""]],"4":[[1,"7","17","Marine spatial plan development (also read at p.13 §4; p.29 §8; p.32 §15; p.32 §16; p.32 §18; p.7 §20; p.29 §10; p.34 §1; p.34 §6)","Complete a Marine Spatial Plan (MSP) for Samoa’s ocean",""]],"5":[[1,"7","19","Ocean monitoring, control, surveillance, and enforcement strengthening (also read at p.14 §8; p.29 §9; p.33 §2; p.33 §3; p.42 §25; p.22 §9)","Strengthen monitoring, control, surveillance and enforcement across Samoa’s ocean",""]],"6":[[1,"7","21","Protection and management of endangered marine migratory species (also read at p.14 §9; p.20 §4; p.29 §11; p.36 §1; p.36 §2; p.36 §4; p.36 §9; p.36 §10; p.42 §28; p.46 §5)","Establish effective protection and management of endangered marine migratory species",""]],"7":[[1,"7","23","Coastal ecosystem services protection policy and legislation strengthening (also read at p.29 §12; p.37 §2; p.37 §3; p.37 §7; p.37 §9; p.37 §11; p.44 §12; p.44 §18)","Strengthen policy and legislation for Coastal Ecosystem Services protection",""]],"8":[[1,"7","24","Ecosystem-based approach integration into climate change adaptation planning (also read at p.29 §13; p.38 §1; p.38 §4; p.38 §7; p.46 §18)","Integrate Ecosystem-Based Approach (EBA) into existing climate change adaptation management plans and initiatives",""]],"9":[[1,"7","25","Deep-sea and seabed exploration risk management legislation (also read at p.26 §7; p.39 §1; p.39 §3)","Review existing policies and establish legislation where appropriate to manage risks posed by deep-sea and seabed exploration",""]],"10":[[1,"7","28","National waste and marine pollution management improvement (also read at p.29 §19; p.41 §1; p.41 §2)","Improve Waste and Marine Pollution management at national level",""]],"11":[[1,"9","3","Ocean stakeholder engagement platform (also read at p.29 §2; p.30 §8; p.30 §11; p.30 §12)","provides a platform for engagement of all relevant partners and donors",""]],"12":[[1,"11","15","Integrated ocean governance approach","an integrated approach to ocean governance",""]],"13":[[1,"13","5","Blue Pacific regional collective action framework","strengthen collective action as one ‘Blue Pacific Continent’",""]],"14":[[1,"14","2","Implementation of international ocean and climate commitments","supports Samoa’s efforts to implement the UN Fish Stocks Agreement",""]],"15":[[1,"14","6","Destructive fishing prohibition and gear regulation (also read at p.42 §26)","free from destructive fishing through prohibition and regulation of fishing methods and gears",""]],"16":[[1,"14","14","Ocean plastics avoidance, interception, and redesign initiative (also read at p.25 §12)","Avoid, intercept and redesign our ocean plastics",""]],"17":[[1,"17","9","Integrated marine resource management solutions","traditional and modern marine resource management and knowledge and information systems",""]],"18":[[1,"20","2","Domestic shipping safety standards enforcement (also read at p.45 §1)","enforce safety standards on domestic shipping",""]],"19":[[1,"22","10","Sustainable aquaculture practices","sustainable aquaculture practices are recognized as important sources of protein",""]],"20":[[1,"23","1","Integration of traditional knowledge and modern ocean science (also read at p.40 §2; p.40 §3; p.40 §3)","combines traditional methods and knowledge with modern science",""]],"21":[[1,"23","2","Youth civic education and participatory governance initiative","an education effort directed toward the next generation will be implemented",""]],"22":[[1,"25","10","Pollution reduction technology and monitoring capacity programme","introduce new pollution reduction technologies",""]],"23":[[1,"25","11","Maritime technology capacity development","there needs to be capacity development in these areas",""]],"24":[[1,"27","7","Invasive species monitoring and port law enforcement (also read at p.33 §16; p.45 §4)","improving monitoring and law enforcement in ports",""]],"25":[[1,"29","5","Formal maritime boundary delimitation (also read at p.31 §1; p.31 §2; p.31 §3; p.44 §9)","Formally define Samoa’s Maritime Boundaries",""]],"26":[[1,"31","10","Samoa ocean business plan development","a business plan is developed for Samoa’s ocean",""]],"27":[[1,"32","8","Academic partnership programme for ocean strategy delivery (also read at p.32 §10; p.32 §11)","partnerships with national and regional academic institutions",""]],"28":[[1,"33","18","Coral reef and mangrove monitoring and enforcement strengthening (also read at p.45 §8)","monitoring and enforcement are strengthened in order to effectively protect coral reefs and mangroves",""]],"29":[[1,"34","16","Official network of coastal and community-managed marine areas (also read at p.46 §1; p.46 §2)","an official network of coastal and community-managed areas, including fish reserves and MPAs, is established",""]],"30":[[1,"34","10","Implementation support memorandum for Samoa's 30 percent marine protection commitment","a Memorandum of Understanding (MOU) is signed",""]],"31":[[1,"37","13","Mangrove protection and restoration policy (also read at p.38 §3; p.44 §17)","mangrove forests are effectively protected or restored through national policy",""]]}});
